insert into public.exam_questions (subject, question, options, answer) values ('소요리', '사람의 제일 되는 목적은 무엇입니까?', '["자신의 행복을 추구하는 것", "하나님을 영화롭게 하는 것과 그를 영원토록 즐거워하는 것", "부와 명예를 얻는 것", "세상에 선한 영향을 미치는 것"]'::jsonb, 1);
