insert into public.exam_questions (subject, question, options, answer) values ('소요리', '그리스도의 직분 중 ''낮아지신 지위''에서 행하신 것은 주로 무엇을 의미합니까?', '["성육신하시고 고난받아 죽으신 것", "사람들에게 존경받으신 것", "세상의 권세를 얻으신 것", "하늘에 오르신 것"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '예수 그리스도는 어떻게 선지자의 직분을 행하십니까?', '["우리를 구원하고자 하시는 하나님의 뜻을 그 말씀과 성령으로 말미암아 우리에게 나타내시는 것", "미래를 예언하심으로만", "죄인을 심판하심으로만", "기적을 행하심으로"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '그리스도께서 선지자 직분을 행하시는 궁극적인 목적은 무엇입니까?', '["자신의 권위를 내세우는 것", "사람들을 놀라게 하는 것", "세상에 지식을 전달하는 것", "사람들을 구원하고자 하시는 하나님의 뜻을 알리는 것"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '그리스도가 참 선지자이신 이유는?', '["죄인인 인간이 하나님을 알 수 없으므로, 하나님께서 직접 자신을 계시하시고 구원의 길을 보이셨기 때문", "가장 많은 추종자를 가졌기 때문", "가장 많은 기적을 행하셨기 때문", "가장 오래 사셨기 때문"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '예수 그리스도는 어떻게 제사장 직분을 행하십니까?', '["사람들에게 죄를 용서할 권한을 주심으로", "단번에 자기를 제물로 드려 하나님의 공의에 만족케 하며, 우리를 하나님으로 더불어 화목케 하시고, 또 우리를 위하여 항상 간구하시는 것", "매일 제사를 드리심으로", "사람들의 죄를 대신하여 심판받으심으로"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '그리스도께서 자신을 제물로 드리신 횟수는?', '["필요할 때마다", "단번에", "여러 번", "매년"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '그리스도의 제사장 직분의 궁극적인 목적은 무엇입니까?', '["세상의 질서를 유지하는 것", "사람들의 병을 고치는 것", "사람들을 가르치는 것", "우리를 하나님으로 더불어 화목케 하는 것"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '그리스도께서 ''우리를 위하여 항상 간구하시는 것''은 현재 어떤 역할을 수행하고 계심을 보여줍니까?', '["통치자", "변호자", "창조자", "심판자"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('소요리', '예수 그리스도는 어떻게 왕의 직분을 행하십니까?', '["우리로 하여금 자기에게 복종케 하시고, 우리를 다스리시며, 보호하시고, 자기와 우리의 모든 원수를 막아 이기시는 것", "모든 사람에게 재물을 주심으로만", "사람들의 육체적인 필요를 채워주심으로만", "세상의 권력을 잡으심으로만"]'::jsonb, 0);
